namespace XmlA1 {
 public static partial class SelfTests {
  static void TestAutomaticDownloads(string root){var library=new XmlLibrary(Path.Combine(root,"auto-dl-lib"),SampleCnpj,1);var states=new StateStore(Path.Combine(root,"auto-dl-state"));var queues=new KeyQueueStore(Path.Combine(root,"auto-dl-queue"));var sciences=new ScienceStore(Path.Combine(root,"auto-dl-science"));var q=new KeyQueue{Uf=35,AutoContinue=true,DownloadAll=true,ScienceForDownload=true,ScienceConsent=DateTime.UtcNow};q.Add(new[]{ReceivedKey(201),ReceivedKey(202),ReceivedKey(203)});queues.Save(SampleCnpj,1,q);Check(queues.Load(SampleCnpj,1).DownloadAll&&queues.Load(SampleCnpj,1).ScienceForDownload&&queues.Load(SampleCnpj,1).Jobs.All(j=>j.AwaitXml),"todas as chaves coladas entram em modo de download persistente");
   var fake=new ScienceFake();fake.Docs.Enqueue(Response("138","1","1",ReceivedInvoice(201)));fake.Docs.Enqueue(Response("138","1","1",ReceivedSummary(202)));fake.Docs.Enqueue(Response("137","0","0"));var batch=new KeyBatchRunner(states,queues,library,fake,null).Run(CancellationToken.None);q=queues.Load(SampleCnpj,1);Check(batch.Downloaded==1&&batch.Pending==2&&q.Jobs[0].Status=="Baixada","só conta XML completo como baixado; resumo e ausência continuam pendentes");Check(q.Jobs[1].Message.Contains("ainda não disponibilizado")&&!q.Jobs[1].Message.Contains("Ciência registrada"),"espera por XML não inventa ciência aceita");Check(q.Jobs[1].NotBefore>DateTime.UtcNow.AddMinutes(59)&&q.Jobs[2].NotBefore>DateTime.UtcNow.AddMinutes(59),"resumo e 137 aguardam uma hora antes de repetir consulta");
   library.Store(ReceivedSummary(204),"4");fake.Events.Enqueue(ScienceReply(ReceivedKey(202)));var scienceRunner=new AutoScienceRunner(states,sciences,queues,library,fake,null);Check(scienceRunner.RunForQueue(35,CancellationToken.None)==1&&fake.Sent==1,"ciência da fila funciona com autorização própria e limitada às chaves pendentes");Check(!sciences.Load(SampleCnpj,1).Enabled&&sciences.Load(SampleCnpj,1).Records.Count==1,"ciência da fila não ativa automação global nem manifesta resumo alheio à fila");
   q=queues.Load(SampleCnpj,1);q.Jobs[1].NotBefore=DateTime.UtcNow.AddMinutes(-1);q.Jobs[2].NotBefore=DateTime.UtcNow.AddHours(1);queues.Save(SampleCnpj,1,q);fake.Docs.Enqueue(Response("138","1","1",ReceivedInvoice(202)));new KeyBatchRunner(states,queues,library,fake,null).Run(CancellationToken.None);Check(queues.Load(SampleCnpj,1).Jobs[1].Status=="Baixada"&&library.List().Any(d=>d.Key==ReceivedKey(202)&&d.Category=="Recebidas"),"download posterior à ciência vai para Recebidas");
   var expiredQueues=new KeyQueueStore(Path.Combine(root,"auto-expired-q"));var expiredScience=new ScienceStore(Path.Combine(root,"auto-expired-science"));var expiredLib=new XmlLibrary(Path.Combine(root,"auto-expired-lib"),SampleCnpj,1);var expired=new KeyQueue{Uf=35,AutoContinue=true,DownloadAll=true,ScienceForDownload=true,ScienceConsent=DateTime.UtcNow};expired.Add(new[]{ReceivedKey(205)});expiredQueues.Save(SampleCnpj,1,expired);expiredLib.Store(ReceivedSummary(205),"1");var expiredClient=new ScienceFake();expiredClient.Events.Enqueue(ScienceReply(ReceivedKey(205),"596"));var expiredRunner=new AutoScienceRunner(states,expiredScience,expiredQueues,expiredLib,expiredClient,null);expiredRunner.RunForQueue(35,CancellationToken.None);Check(expiredQueues.Load(SampleCnpj,1).Jobs[0].AwaitXml&&expiredQueues.Load(SampleCnpj,1).Jobs[0].ScienceCode=="596","596 mantém tentativa automática de XML no modo baixar todas");expiredClient.Docs.Enqueue(Response("138","1","1",ReceivedSummary(205)));new KeyBatchRunner(states,expiredQueues,expiredLib,expiredClient,null).Run(CancellationToken.None);Check(expiredQueues.Load(SampleCnpj,1).Pending==1&&expiredQueues.Load(SampleCnpj,1).Jobs[0].Message.Contains("rejeitada por prazo"),"596 seguido de resumo aguarda download em vez de encerrar chave");expiredRunner.RunForQueue(35,CancellationToken.None);Check(expiredClient.Sent==1,"espera por XML não reenvia ciência 596");expired=expiredQueues.Load(SampleCnpj,1);expired.Jobs[0].NotBefore=DateTime.UtcNow.AddMinutes(-1);expired.Jobs[0].XmlChecks=23;expiredQueues.Save(SampleCnpj,1,expired);expiredClient.Docs.Enqueue(Response("137","0","0"));new KeyBatchRunner(states,expiredQueues,expiredLib,expiredClient,null).Run(CancellationToken.None);expired=expiredQueues.Load(SampleCnpj,1);Check(expired.Pending==1&&expired.AutoContinue&&expired.Jobs[0].NotBefore>DateTime.UtcNow.AddHours(5.9),"após 24 verificações mantém download com intervalo de seis horas");expired.Jobs[0].NotBefore=DateTime.UtcNow.AddMinutes(-1);expiredQueues.Save(SampleCnpj,1,expired);expiredClient.Docs.Enqueue(Response("138","1","1",ReceivedInvoice(205)));new KeyBatchRunner(states,expiredQueues,expiredLib,expiredClient,null).Run(CancellationToken.None);Check(expiredQueues.Load(SampleCnpj,1).Jobs[0].Status=="Baixada"&&expiredClient.Sent==1,"XML liberado após espera prolongada é baixado sem novo evento");
   var noConsentQueues=new KeyQueueStore(Path.Combine(root,"auto-no-consent-q"));var noConsent=new KeyQueue{Uf=35,DownloadAll=true,ScienceForDownload=true};noConsent.Add(new[]{ReceivedKey(204)});noConsentQueues.Save(SampleCnpj,1,noConsent);var noEvent=new ScienceFake();Check(new AutoScienceRunner(states,sciences,noConsentQueues,library,noEvent,null).RunForQueue(35,CancellationToken.None)==0&&noEvent.Sent==0,"não envia ciência da fila sem autorização registrada");
   var migration=new KeyQueue();migration.Add(Enumerable.Range(210,6).Select(ReceivedKey));string[] statuses={"Resumo / eventos","Necessita manifestação","Não encontrada","XML indisponível","Baixada","Rejeitada"};for(int i=0;i<statuses.Length;i++)migration.Jobs[i].Status=statuses[i];Check(migration.StartDownloads()==4&&migration.Pending==4&&migration.Jobs.Take(4).All(j=>j.AwaitXml)&&migration.Jobs[4].Status=="Baixada"&&migration.Jobs[5].Status=="Rejeitada","iniciar download recupera resultados antigos sem repetir baixadas ou rejeições definitivas");
   var fairStates=new StateStore(Path.Combine(root,"auto-fair-state"));var fairQueues=new KeyQueueStore(Path.Combine(root,"auto-fair-q"));var fair=new KeyQueue{Uf=35,AutoContinue=true,DownloadAll=true};fair.Add(Enumerable.Range(300,22).Select(ReceivedKey));fairQueues.Save(SampleCnpj,1,fair);var fairClient=new ScienceFake();for(int i=0;i<20;i++)fairClient.Docs.Enqueue(Response("137","0","0"));new KeyBatchRunner(fairStates,fairQueues,library,fairClient,null).Run(CancellationToken.None);Check(fairClient.Queries==20&&fairQueues.Load(SampleCnpj,1).Pending==22,"22 chaves ficam pendentes ao alcançar vinte chamadas");var cursor=fairStates.Load(SampleCnpj,1);cursor.KeyQueries=cursor.KeyQueries.Select(t=>t.AddHours(-2)).ToList();fairStates.Save(SampleCnpj,1,cursor);fair=fairQueues.Load(SampleCnpj,1);foreach(var job in fair.Jobs)job.NotBefore=DateTime.MinValue;fairQueues.Save(SampleCnpj,1,fair);fairClient.Docs.Enqueue(Response("138","1","1",ReceivedInvoice(320)));fairClient.Docs.Enqueue(Response("138","1","1",ReceivedInvoice(321)));for(int i=0;i<18;i++)fairClient.Docs.Enqueue(Response("137","0","0"));new KeyBatchRunner(fairStates,fairQueues,library,fairClient,null).Run(CancellationToken.None);fair=fairQueues.Load(SampleCnpj,1);Check(fair.Jobs[20].Status=="Baixada"&&fair.Jobs[21].Status=="Baixada","chaves ainda não consultadas têm prioridade sobre reconsultas antigas");
   var rejectedQueues=new KeyQueueStore(Path.Combine(root,"auto-rejected-q"));var rejected=new KeyQueue{Uf=35,DownloadAll=true,AutoContinue=true};rejected.Add(new[]{ReceivedKey(400)});rejectedQueues.Save(SampleCnpj,1,rejected);var rejectedClient=new ScienceFake();rejectedClient.Docs.Enqueue(Response("632","0","0"));new KeyBatchRunner(states,rejectedQueues,library,rejectedClient,null).Run(CancellationToken.None);Check(rejectedQueues.Load(SampleCnpj,1).Jobs[0].Status=="Rejeitada"&&rejectedQueues.Load(SampleCnpj,1).Pending==0,"prazo de distribuição encerrado é mostrado sem fingir download");
  }
 }
